#define main historical_main
#include "../hellinger-cuda/main.cu"
#undef main
#include <vector>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{float*a,*b,*c;std::vector<float>expected;std::vector<double>gold;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;int rows=32,terms=64,cols=48;std::vector<float>b(terms*cols);srand(123);for(float&x:b)x=rand()%256;for(int col=0;col<cols;col++){float s=0;for(int i=0;i<terms;i++)s+=b[i*cols+col];for(int i=0;i<terms;i++)b[i*cols+col]/=s;}std::vector<Case>cases;for(int kind=0;kind<=1;kind++){Case c;std::vector<float>a(rows*terms,1.f/terms);if(kind){for(int row=0;row<rows;row++){float sum=0;for(int i=0;i<terms;i++){a[row*terms+i]=(row*13+i*7)%17+1;sum+=a[row*terms+i];}for(int i=0;i<terms;i++)a[row*terms+i]/=sum;}}c.expected.resize(rows*cols);c.gold.resize(rows*cols);for(int row=0;row<rows;row++)for(int col=0;col<cols;col++){float s=0;double ds=0;for(int i=0;i<terms;i++){s+=sqrtf(a[row*terms+i]*b[i*cols+col]);ds+=sqrt(double(a[row*terms+i])*b[i*cols+col]);}float v=1-s;c.expected[row*cols+col]=sqrtf((!std::signbit(v))*v);c.gold[row*cols+col]=sqrt(fmax(0.,1.-ds));}CK(cudaMalloc(&c.a,a.size()*sizeof(float)));CK(cudaMalloc(&c.b,b.size()*sizeof(float)));CK(cudaMalloc(&c.c,c.expected.size()*sizeof(float)));CK(cudaMemcpy(c.a,a.data(),a.size()*sizeof(float),cudaMemcpyHostToDevice));CK(cudaMemcpy(c.b,b.data(),b.size()*sizeof(float),cudaMemcpyHostToDevice));hellinger<<<dim3(3,2),dim3(16,16)>>>(c.a,c.b,c.c,rows,terms,cols);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;
for(int trial=1;trial<=5;trial++){double seconds=0,ma=0,de=0;std::vector<float>out;bool ok=true;for(auto&c:cases){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)hellinger<<<dim3(3,2),dim3(16,16)>>>(c.a,c.b,c.c,rows,terms,cols);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<float>got(c.expected.size());CK(cudaMemcpy(got.data(),c.c,got.size()*sizeof(float),cudaMemcpyDeviceToHost));for(int i=0;i<(int)got.size();i++){ma=fmax(ma,fabs(got[i]-c.expected[i]));de=fmax(de,fabs(got[i]-c.gold[i]));ok&=std::isfinite(got[i])&&got[i]>=0&&got[i]<=1&&fabs(got[i]-c.expected[i])<1e-5&&fabs(got[i]-c.gold[i])<1e-5;}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"hellinger_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(float),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"float64_oracle_max_error\":%.12g,\"timing_region\":\"sum_uniform_and_nonuniform_normalized_probability_hellinger_matrices\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,de,repeat,file,out.size());}for(auto&c:cases){CK(cudaFree(c.a));CK(cudaFree(c.b));CK(cudaFree(c.c));}puts(allok?"PASS":"FAIL");return allok?0:1;}
